"""Human development report and current notes; historical artifacts stay intact."""
from .common import *
import gzip,shutil

def pct(n,d):return '—' if not d else f'{100*n/d:.1f}%'
def fm(v):return '—' if v is None else f'{v:.5f}'
def decision(analyses,summary,stability):
 if not summary:return 'Repair a specific remaining component: development collection/analysis is incomplete.'
 pt=summary['point']['full_field'];ci=summary['CI95']['full_field'];a='all_in/uncertain/A_minus_Full_brier';b='all_in/uncertain/B_plus_fallback_minus_Full_brier';times=[v for r in analyses for v in r.get('meaningful_update_with_readout_samples',[])];recovery=[v['elapsed_seconds'] for r in analyses for v in r.get('recoveries',[])];import numpy as np
 checks=dict(all_native=summary['native_completed']==296,all_scored=summary.get('complete_field_inference_valid',False),supported_90=pt.get('coverage/full_supported',0)>=.9,uncertain_A_gain_005=pt.get(a,-1)>=.005 and ci.get(a,[-1])[0]>0,location_B_gain=pt.get(b,-1)>0 and ci.get(b,[-1])[0]>0,ECE_05=pt.get('all_in/all/Full_plus_fallback/ECE',1)<=.05,update_p95_50ms=bool(times) and np.quantile(times,.95)<=.05,reconstruction_p95_1s=not recovery or np.quantile(recovery,.95)<=1,RSS_512=max((r.get('incremental_RSS_MiB',9999) for r in analyses),default=9999)<=512,stability_02=stability is not None and stability.get('mean_abs_probability_discrepancy') is not None and stability['mean_abs_probability_discrepancy']<=.02 and stability['mean_paired_point_coverage']==1)
 if all(checks.values()):recommend='Freeze this implementation for a later, separately authorized held-out evaluation. Development is exploratory; do not launch held-out or PPO now.'
 elif not checks['all_scored']:recommend='Repair the remaining exact-fact/observer-analysis failures recorded by signature before freezing for held-out evaluation.'
 elif not checks['supported_90']:recommend='Repair finite-stratum reconstruction and unresolved effect support: full selected-decision coverage remains below 90%. Do not proceed to held-out evaluation or PPO.'
 elif not checks['update_p95_50ms'] or not checks['reconstruction_p95_1s']:recommend='Repair the measured update/reconstruction cost before freezing for held-out evaluation.'
 else:recommend='Simplify to the certified-fact baseline: these exploratory development diagnostics do not establish sufficient additional value from the full filter.'
 write(OUT/'development-readiness.json',dict(at_utc=iso(),checks={k:bool(v) for k,v in checks.items()},recommendation=recommend,exploratory_only=True,held_out_authorized=False,PPO_authorized=False));return recommend

def current_note(path,state,reason):
 start='<!-- BELIEF-DEV003-CURRENT -->';end='<!-- BELIEF-DEV003-CURRENT-END -->';old=path.read_text(encoding='utf-8-sig') if path.exists() else '';archive=OUT/'historical'/path.name
 if not archive.exists():archive.parent.mkdir(exist_ok=True);archive.write_text(old,encoding='utf-8')
 if start in old:a=old.index(start);b=old.index(end,a)+len(end);old=old[:a]+old[b:].lstrip('\n')
 note=f'{start}\n## Current development repair003\n\n{iso()}: **{state}**. {reason} The current scope is296 development completions (six retained +290 new); held-out296 remains untouched. This note supersedes the historical run001/run002 recommendations below. [Current repair report](astra-unown-belief-development-repair.md).\n{end}\n\n'
 path.write_text(note+old,encoding='utf-8')

def render(state,reason,final=False):
 native=rows(OUT/'native-matches.jsonl');analyses=rows(OUT/'analysis-records.jsonl');summary=read(OUT/'development-analysis.json') if (OUT/'development-analysis.json').exists() else None;stability=read(OUT/'stability-summary.json') if (OUT/'stability-summary.json').exists() else None;cost=read(OUT/'completion.json') if (OUT/'completion.json').exists() else None
 text=f'# Belief observer development repair\n\nState: **{state}**. Updated {iso()}.\n\n{reason}\n\n'
 text+=f'Historical run001 used zero native matches. Run002’s six native BO3 completions, five scored records and area14 analysis failure are unchanged. Repair003 retains those six and authorizes only the 290 previously unattempted development IDs. New collection records: {len(native)}; new native completions: {sum(r.get("native_collection_status")=="COMPLETE" for r in native)}; new aligned truth records: {sum(r.get("truth_alignment_status")=="COMPLETE" for r in native)}. **Held-out collection, inspection and scoring: zero.** No match replacement or rerun is authorized.\n\n'
 text+='## Verified native semantics\n\nThe official C++ SDK’s Types.h assigns 13=Playing and 14=DeckBottom. State::pushCardRef sends Deck to push_back (native top) and DeckBottom to push_front (native bottom); CardMove::MoveCard keeps 14 in the movement log but normalizes the stored area to Deck. DeckBottom is a destination alias, not a separate pile or a valid source. EffectInstant::ToDeckBottomClose shuffles the target list, then moves each card with openType2. CardImpl’s Metang86 chain is LookDeck4 → selected Metal attachments → ToDeckBottomClose. Thus the failed four-card return shuffles only that returned block, preserves the rest of the deck, and fixes the block at the bottom. This proof uses native implementation, not card text or area-pair guessing. Source/binary hashes and exact symbols are in native-area-semantics.json.\n\n'
 text+='The old Python sample enum omitted both 13 and 14. The audit also distinguishes storage areas from All and selector/reference/internal values 15–24; unexpected physical use is explicit unsupported semantics. Temporary source 24 is normalized to the card’s original area by native MoveCard before logging. The new compiler, physical particles, certified-fact observer and A/B baseline use the same destination semantics. Known bottom copies remain protected until top draws reach their suffix. Ambiguous conditional suffix removal remains an explicit baseline failure rather than invented order.\n\n'
 text+='## Fallback diagnosis and bounded repair\n\nRun002 stopped the entire aggregate on the first depleted compatible stratum and then skipped compilation for the rest of the BO3. Its single degraded flag survived new-game boundaries. This was a conservative global readout latch, not proof the deck was impossible. Failed strata had material estimated masses, including one 100% case. Old replay diagnostics reproduce the original callback counts exactly.\n\n'
 if (OUT/'legacy-first-fallbacks.json').exists():
  legacy=read(OUT/'legacy-first-fallbacks.json');witness={r['id']:r for r in read(OUT/'compatibility-witnesses.json')} if (OUT/'compatibility-witnesses.json').exists() else {};text+='| Retained match | First callback/game/turn | Cause and hypothesis | Pre-event mass | Compatible allocation evidence |\n|---|---|---|---:|---|\n'
  for row in legacy:
   first=row['first_fallback'];w=witness.get(row['id'],{})
   if not first:text+=f'| {row["id"]} | — | No fallback | — | Full original support |\n';continue
   rs=first['reason'];h=rs.get('hypothesis');mass=rs.get('pre_event_masses',{}).get(h);label=rs['kind']+' '+(h[:10] if h else rs.get('message',''));text+=f'| {row["id"]} | {first["observation_index"]}/{first["game"]}/{first["turn"]} | {label} | {fm(mass)} | {w.get("compatible_allocation","not established")} |\n'
  text+='\nEach numerical cause retains its exact typed event, legal context, original recovery failure histogram and normalized pre-event masses in legacy-first-fallbacks.json. The separate diagnostic uses one 2048-state, seed 11 replay per first-depletion prefix; it does not change the primary 512 population. A successful witness proves compatibility under the saved typed history; failure is unresolved, never proof of impossibility. Unsupported search semantics cannot be adjudicated by a numerical witness alone.\n\n'
 text+='The first failed events were 1407 hand→playing, 1219 hand→playing, 920 hand→public board, and 1097 hand→playing. Original 256-state recovery returned zero survivors: availability contradictions dominated; 1219 and 920 also failed joint chance-location plans, and 1097 failed a known-copy hand location. The b1a history instead stopped at an unresolved concealed deck→hand selection while a stale 1182 effect remained in context; no particle increase could fix that compiler omission. All four numerical first-failure prefixes now have valid 2048-state replay witnesses. This establishes finite reconstruction/proposal failure rather than an impossible list for these examples. Exact event payloads and per-cause counts remain in the linked diagnosis file.\n\n'
 text+='The repair separates true history-order pins from auxiliary proposal pins. Auxiliary pins expire after the guided chance segment; true known/latent top-bottom history constraints survive until consumed or explicitly shuffled. Verified native unrevealed deck-search profiles use positive availability and a declared uniform latent selection, not a random-draw likelihood. These repairs are tested against small exact cases and the six retained histories.\n\n'
 text+='Numerically unresolved hypotheses keep their identities and evidence status; healthy strata continue updating. Full readout remains fallback while any compatible stratum lacks complete-prefix evidence. Recovery can resume after later callbacks or a new game only by reconstructing the complete missing prefix and multiplying the original prior by cached completed-game likelihood estimates and the current-game estimate exactly once. No prior mass is restored or failed list silently dropped. A hard public composition contradiction may remove a list; finite depletion may not. Unsupported past semantics still block a justified full posterior across later games.\n\n'
 text+='Primary population 512, floor 4, auxiliary recovery 256 remain fixed; the stability population 2048 uses auxiliary 1024. Retries are deterministic: at most four/game, at least 16 callbacks apart, with a 2,000,000 proposal-state-step BO3 cap (8,000,000 at2048). Completed-game caches store likelihood estimates, not hand/order state. Log evidence is retained; a -700 display/allocation exponent floor prevents floating-point disappearance of compatible strata. Normalized SMC remains approximate.\n\n'
 if (OUT/'six-repaired-replays.json').exists():
  results=read(OUT/'six-repaired-replays.json');old={r['id']:r for r in read(OUT/'inherited-native-records.json')};text+='### Six-history development diagnostics\n\n| Match | Original supported/fallback callbacks | Repaired supported/fallback callbacks | Repaired selected coverage | Scoring | CPU s |\n|---|---:|---:|---:|---|---:|\n'
  for r in results:
   previous=old[r['id']].get('belief_counts',{});cs=r['callbacks'];text+=f'| {r["id"]} | {previous.get("SUPPORTED","unscored")}/{previous.get("FALLBACK",0) if previous else "unscored"} | {cs.get("SUPPORTED",0)}/{cs.get("FALLBACK",0)} | {pct(r.get("support",0),1)} | {r["scoring"]} | {r["CPU_seconds"]:.2f} |\n'
  text+='\nCallback coverage and selected-decision coverage have different denominators. These reused histories informed implementation; original-versus-repaired differences are development diagnostics, not independent evidence of predictive improvement. Detailed repaired analyses, conservation/copy assertions, timing and failure examples remain separate from run002.\n\n'
 if (OUT/'pytest.json').exists():
  test=read(OUT/'pytest.json');inv=read(OUT/'isolation-and-invariants.json');text+=f'## Verification before collection\n\n{test["tests"]} focused tests passed using synthetic inputs and retained histories, with zero new native diagnostics. The actual area14 history replays and scores completely. The independent isolation check compared {inv["checks"]["hidden_truth_and_scheduled_ID_invariant_callbacks"]} callbacks after changing forbidden hidden-hand/diagnostic/scheduled-list fields and global RNG draws, checked {inv["particle_states_checked"]:,} live particle states, verified duplicate callbacks, particle conservation, physical serial facts, fixed weights, all frozen policy files and all six original corpus/label hashes. Exact-reference tests cover top/bottom order and completed-game evidence without reset or double counting. The pinned CPU runtime, tests and history checks are linked in the run directory.\n\n'
 text+='## Collection and analysis contract\n\nBoth actors retain submission 57834515, the existing adapter, fixed deck and conditional argmax for each BO3. Initial chooser rights retain the original 4/4 allocation per list; actors choose actual starting order. Forced observations still update policy memory. Tracker features, diagnostic truth and scheduled opponent identity never enter actor input; observer construction receives the full 37-list library/prior and its own RNG, not the true scheduled list. Native deals are independent and policy seeds do not control native randomness.\n\n'
 text+='Collection, truth alignment, observer analysis and scoring have separate status fields. Observer exceptions are grouped offline and cannot erase a native game or issue a replacement. Actor errors, policy mutation, invalid chooser handling, information leakage, unusable corpus/truth alignment or resource exhaustion stop collection. An append-only attempt ledger and exclusive worker intents prohibit duplicate or ambiguous reissues. Legal streams and separate truth labels remain private; sampling retains the original lowest-hash 24 genuine decisions/game.\n\n'
 text+='Scores retain query→decision→game→BO3→equal chooser→n/100 or passing-pool n/82 aggregation, fixed tactical categories and A∈[.10,.90] uncertain queries. 20,000 paired whole-BO3 bootstrap draws use shared indices within list/chooser. Failed analyses retain explicit expected-point and population coverage; metrics on available scores are labeled conditional. Missing strata/matches never establish complete-field improvement, and no missing prediction is fabricated. Supported-only and Full-plus-A-fallback/B-plus-A-fallback are separate.\n\n'
 if summary:
  text+='## Complete development analysis\n\n'+f'Native corpus: {summary["native_completed"]}/296; scoring failures: {summary["analysis_failures"]}; complete-field scoring valid: {summary["complete_field_inference_valid"]}. These results are **exploratory development**, with implementation selected using this corpus.\n\n'
  for population in ('full_field','eligible'):
   pt=summary['point'][population];ci=summary['CI95'][population];cov=summary['population_weight_coverage'][population];text+=f'### {population}\n\n| Query/scope | Method | Brier | Hand MAE | Deck MAE | Prize MAE | ECE | Score coverage |\n|---|---|---:|---:|---:|---:|---:|---:|\n'
   for scope in ('all_in','supported_only'):
    for group in ('all','uncertain'):
     for method in ('A','B_plus_fallback','Full_plus_fallback'):
      pre=f'{scope}/{group}/{method}';text+=f'| {scope}/{group} | {method} | '+' | '.join(fm(pt.get(pre+'/'+metric)) for metric in ('brier','hand_MAE','deck_MAE','prize_MAE','ECE'))+f' | {pct(cov.get(pre+"/brier",0),1)} |\n'
   text+='\n'
   for key,value in pt.items():
    if '_minus_Full_brier' in key:text+=f'- {key}: {value:+.5f}, paired95% interval {ci.get(key)}.\n'
   text+='\n'
  text+='### Every frozen list\n\n| Hash/family | Native/scored | BO3 W/D/L | First W/D/L | Learner actually first, game1 | Supported callbacks | Supported selected decisions |\n|---|---:|---|---|---:|---:|---:|\n'
  native_all=read(OUT/'development-corpus.json');lookup={r['id']:r for r in analyses}
  for d,v in prior().items():
   ns=[r for r in native_all if r['opponent_list']==d];rs=[lookup[r['id']] for r in ns if r['id'] in lookup]
   def wdl(first=False):
    return '/'.join(str(sum((r['games'][0]['result'] if first else r['result'])==z(r['seat']) for r in ns)) for z in (lambda s:s,lambda s:2,lambda s:1-s))
   obs=sum(r.get('observation_expected',0) for r in rs);obsS=sum(r.get('belief_counts',{}).get('SUPPORTED',0) for r in rs);sel=sum(r.get('selected_expected',0) for r in rs);selS=sum(r.get('supported_selected',0) for r in rs);scored=sum(r.get('scoring_status')=='COMPLETE' for r in rs);actual=sum(r['games'][0]['first_player']==r['seat'] for r in ns);text+=f'| {d[:10]} {v["archetype"]} | {len(ns)}/{scored} | {wdl()} | {wdl(True)} | {actual} | {obsS}/{obs} | {selS}/{sel} |\n'
  text+='\nBO3 and first-game win-rate uncertainty is retained with the same whole-match bootstrap in development-analysis.json; draws remain denominators. Later games and actual starting order are descriptive. Recorded per-game chooser, starter, outcomes and termination labels remain in compact native records.\n\n'
  groups=collections.defaultdict(collections.Counter);families=collections.defaultdict(collections.Counter);causes=collections.Counter();later=0
  for r in analyses:
   for g,x in r.get('coverage_by_game_stage',{}).items():groups[g].update(x)
   f=prior()[r['opponent_list']]['archetype'];families[f].update(dict(observations_expected=r.get('observation_expected',0),supported_observations=r.get('belief_counts',{}).get('SUPPORTED',0),selected_expected=r.get('selected_expected',0),supported_selected=r.get('supported_selected',0)))
   first=r.get('first_fallback')
   if first:causes[first['reason']['kind']]+=1;later+=r.get('later_selected_affected',0)
  text+='### Coverage by game/stage and archetype\n\n| Group | Supported callbacks / expected | Supported selected / expected |\n|---|---:|---:|\n'
  for name,x in sorted({**dict(groups),**{'family:'+k:v for k,v in families.items()}}.items()):text+=f'| {name} | {x["supported_observations"]}/{x["observations_expected"]} | {x["supported_selected"]}/{x["selected_expected"]} |\n'
  text+=f'\nFirst-fallback causes: {dict(causes)}. Later selected decisions affected: {later}. Analysis/scoring failures are separate from full-filter unsupported/depletion and from native/truth failures. Each match’s first event, unresolved lists, masses and resumed-readout transitions remain in analysis records/private diagnostic artifacts.\n\n'
 if stability:text+=f'## Offline stability\n\n{stability["replays"]} replays on 16 frozen development IDs, budgets 512/2048 and seeds 11/29/47; no extra native matches. All-in mean absolute probability discrepancy {fm(stability["mean_abs_probability_discrepancy"])}; paired-point coverage {pct(stability["mean_paired_point_coverage"],1)}. Shared-full differences, support disagreement, Brier and failures are reported by pair. Larger budget is a convergence comparison, not ground truth; agreement caused by A fallback is explicitly distinguished.\n\n'
 if analyses:
  signatures=collections.Counter(r.get('analysis_failure_signature') for r in analyses if r.get('analysis_failure_signature'));text+=f'## Analysis failures\n\n{dict(signatures) if signatures else "No observer/scoring exceptions recorded."} Detailed examples stay private and replayable. Valid native games remain in the corpus.\n\n'
 recommend=decision(analyses,summary,stability) if final else 'Initial repairs are validated; complete development collection and offline diagnostics only. No held-out evaluation or PPO is authorized.'
 text+='## Decision and costs\n\n**Recommendation:** '+recommend+'\n\n'
 if cost:text+=f'Execution: {cost.get("wall_seconds",0)/3600:.3f} UTC hours; worker CPU {cost.get("worker_CPU_seconds",0)/3600:.3f} core-hours; controller CPU {cost.get("controller_CPU_seconds",0):.2f}s; private storage {cost.get("storage_bytes",0)/1024**2:.2f}MiB. Preparation/replay readiness costs are recorded separately. Fresh deadline: {deadline().isoformat()}. At most four local workers and one Torch thread. GPU 0, training 0, uploads 0, submissions 0, paid model API calls 0; no power-plan changes or sleep inhibition.\n\n'
 if (OUT/'preparation-costs.json').exists():
  prep=read(OUT/'preparation-costs.json');forecast=read(OUT/'forecast.json');text+=f'Preparation elapsed at freeze: {prep["UTC_elapsed_seconds"]/60:.1f} minutes; metered replay/witness/isolation CPU subtotal {prep["metered_replay_witness_isolation_CPU_seconds"]:.1f}s. Earlier inspection, legacy reproduction and setup CPU were not all metered, so this is a lower bound rather than total preparation CPU. Expected execution 1–3 hours; conservative forecast {forecast["conservative_elapsed_seconds"]/3600:.2f} hours, using complete retained workloads, four workers, a 3× margin and startup/analysis allowance. The fixed deadline includes preparation and is not extended by sleep.\n\n'
 text+='Evidence: [registration](../experiments/'+RUN+'/registration.json), [ledger](../experiments/'+RUN+'/attempt-ledger.jsonl), [native-area semantics](../experiments/'+RUN+'/native-area-semantics.json), [first-fallback diagnoses](../experiments/'+RUN+'/legacy-first-fallbacks.json), [compatibility witnesses](../experiments/'+RUN+'/compatibility-witnesses.json), [source manifest](../experiments/'+RUN+'/source-manifest.json), [development analysis](../experiments/'+RUN+'/development-analysis.json), [completion/cost](../experiments/'+RUN+'/completion.json). Historical run002 files remain unchanged; a guard manifest verifies this.\n'
 REPORT.write_text(text,encoding='utf-8')
 for name in ('astra-unown-belief-native-observer-readiness.md','astra-unown-belief-tracker-validation.md'):current_note(R/'reports'/name,state,recommend)
 status=R/'docs/STATUS.md';old=status.read_text(encoding='utf-8-sig');start='<!-- BELIEF-DEV003-STATUS -->';end='<!-- BELIEF-DEV003-STATUS-END -->'
 if start in old:a=old.index(start);b=old.index(end,a)+len(end);old=old[:a]+old[b:].lstrip('\n')
 status.write_text(f'{start}\n## Belief observer development repair003\n\n{iso()}: **{state}**. Six retained +{sum(r.get("native_collection_status")=="COMPLETE" for r in native)} new native completions; target296 development only, held-out untouched. {recommend} [Report](../reports/astra-unown-belief-development-repair.md).\n{end}\n\n'+old,encoding='utf-8')
 mirror=Path('C:/path/to/ptcg-agent') if os.name=='nt' else Path('/path/to/ptcg-agent')
 sources=[REPORT,status,R/'reports/astra-unown-belief-native-observer-readiness.md',R/'reports/astra-unown-belief-tracker-validation.md']+[OUT/f for f in ('registration.json','source-manifest.json','native-gate.json','launch.json','startup.json','progress.json','completion.json','native-area-semantics.json','legacy-first-fallbacks.json','compatibility-witnesses.json')]
 if final:sources +=[p for p in OUT.iterdir() if p.is_file() and p.suffix in ('.json','.jsonl','.md')]
 for source in sources:
  if source.exists():target=mirror/source.relative_to(R);target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(source,target)
